Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <fstream>
#include <cmath>
using namespace std;

typedef long long ll;
typedef long double ld;

int x, y, n;

int nod(int a, int b) {
    if (a == 0) return b;
    if (b == 0) return a;
    return nod(b, a % b);
}

int main() {
#ifndef ONLINE_JUDGE
#define cin fin
    ifstream fin("omg.txt");
#endif
    cin >> x >> y >> n;

    ll a, b;

    if (n >= y) {
        int g = nod(x, y);
        a = x / g;
        b = y / g;
    } else {
        ld best = 1000050000.;
        ld target = (ld)x / y;

        for (int i = 1; i <= n; ++i) {
            ld value = (ld)x * i / y;
            ld cand[2];
            cand[0] = floorl(value);
            cand[1] = ceill(value);

            for (int j = 0; j < 2; ++j) {
                ld err = std::abs(cand[j] / i - target);
                if (err < best) {
                    a = (ll)cand[j];
                    b = i;
                    best = err;
                }
            }
        }
    }

    cout << a << "/" << b << endl;
    return 0;
}
